import sys
from itertools import combinations

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    k = int(input[1])
    cards = [(int(input[3*i]), int(input[3*i+1]), int(input[3*i+2])) for i in range(n)]

    result = -1
    for level in range(1, n + 1):
        valid_cards = [card for card in cards if card[2] <= level]
        for r in range(1, len(valid_cards) + 1):
            for deck in combinations(valid_cards, r):
                if sum(card[0] for card in deck) >= k:
                    if not any(is_prime(sum(card[1] for card in deck_subset)) for deck_subset in combinations(deck, 2)):
                        result = level
                        break
            if result != -1:
                break
        if result != -1:
            break

    print(result)

main()
